// Member and manifest-row counts follow the generated member pins, never a fixed number.
// test.py runs this file twice per test run:
//   - with the release's own FirmwarePins.h on that release's unzipped ZIP (C21 on 1.0.6.11: 17 members
//     and a 16-row manifest);
//   - with a fixture pins header (-include, generated by test.py from the stock 1.0.6.11 ZIP of the
//     tree's base) on that unzipped ZIP: 17 members and a 16-row manifest, rives.bin gone, nuttx_ota.bin
//     and amap_rtos_sdk new, amap_rtos_sdk with a BurnPath in a subfolder (loadable/libs/).
// Mode "pathpin" runs a fixture whose pins name one member with a path ("loadable/libs/amap_rtos_sdk"):
// the folder check must refuse it whether the file sits flat or in that subfolder.
// Mode "rows" runs a fixture folder whose manifest lacks one row while its pins match the folder: the folder
// check passes, and the gate's preparation refuses with the manifest-row message (no silent stall).
// Mode "rows-extra" is the same with one invented row too many (n rows against n member pins): test.py runs it
// on the stock 1.0.6.11 folder (17 rows, 17 pins) and on the release's own folder (17 rows, 17 pins for C21).
// In mode "pins" the flash gate (TIOOTAFlashGate, the unchanged phone code) also takes the folder through a
// whole transfer: Mode 2, the target version, the manifest of n-1 rows and every slice of every member.
// argv: <unzipped folder> <the ZIP> <pins|pathpin|rows|rows-extra>. No device, network or signing.
#import "ExperimentalOTA.h"
#import "ExperimentalOTAFlash.h"
#import "FirmwarePins.h"
#import "TIOLanguage.h"
#include <assert.h>
static void V(NSMutableData *d,NSUInteger n){do{uint8_t b=n&127;n>>=7;if(n)b|=128;[d appendBytes:&b length:1];}while(n);}
static NSData *F(NSUInteger type,id json,NSData *binary){NSMutableData *d=[NSMutableData new];V(d,8);V(d,1);V(d,16);V(d,type);if(json){NSData *j=[NSJSONSerialization dataWithJSONObject:json options:0 error:nil];V(d,26);V(d,j.length);[d appendData:j];}if(binary){V(d,34);V(d,binary.length);[d appendData:binary];}return d;}
static NSURL *Copy(NSURL *from,NSURL *root,NSString *name){
    NSURL *to=[root URLByAppendingPathComponent:name isDirectory:YES];assert([NSFileManager.defaultManager copyItemAtURL:from toURL:to error:nil]);return to;
}
int main(int argc,const char **argv){@autoreleasepool{
    assert(argc==4);NSFileManager *fm=NSFileManager.defaultManager;NSError *error=nil;
    NSURL *folder=[NSURL fileURLWithPath:@(argv[1]) isDirectory:YES];NSString *mode=@(argv[3]);
    NSDictionary *pins=TIO_FW_MEMBER_PINS;NSUInteger n=pins.count;
    assert(TIOExperimentalOTAMemberCount()==n&&n>=3);
    NSURL *root=[NSURL fileURLWithPath:[NSTemporaryDirectory() stringByAppendingPathComponent:[@"tio-member-count-" stringByAppendingString:NSUUID.UUID.UUIDString]] isDirectory:YES];
    assert([fm createDirectoryAtURL:root withIntermediateDirectories:NO attributes:@{NSFilePosixPermissions:@0700} error:nil]);
    if([mode isEqual:@"pathpin"]){
        // One pin names a path: refused flat (the pinned name is missing) and in the subfolder (a directory entry).
        NSString *pathName=nil;for(NSString *name in pins)if([name containsString:@"/"])pathName=name;assert(pathName);
        NSURL *flat=Copy(folder,root,@"flat");
        assert(!TIOCheckExperimentalOTADirectory(flat,&error)&&error);
        NSURL *nested=Copy(folder,root,@"nested");NSURL *target=[nested URLByAppendingPathComponent:pathName];
        assert([fm createDirectoryAtURL:target.URLByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil]);
        assert([fm moveItemAtURL:[nested URLByAppendingPathComponent:pathName.lastPathComponent] toURL:target error:nil]);
        error=nil;assert(!TIOCheckExperimentalOTADirectory(nested,&error)&&error);
        assert(!TIOCopyExperimentalOTAPayloads(nested,nil)&&!TIOCopyExperimentalOTAPayloads(flat,nil));
        assert([fm removeItemAtURL:root error:nil]);
        NSLog(@"PASS: a member pin holding a path (%@) is refused, flat and in its subfolder",pathName);
        return 0;
    }
    if([mode isEqual:@"rows"]||[mode isEqual:@"rows-extra"]){
        NSUInteger expected=[mode isEqual:@"rows"]?n-2:n;
        NSDictionary *good=TIOCheckExperimentalOTADirectory(folder,&error);assert(good&&!error&&[good[@"checkedMembers"] unsignedIntegerValue]==n);
        NSArray *rows=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfURL:[folder URLByAppendingPathComponent:@"OtaFileInfo.json"]] options:0 error:nil];assert(rows.count==expected);
        TIOOTAFlashGate *g=[TIOOTAFlashGate new];error=nil;
        assert(![g prepareDirectory:folder device:@"TEST_DEVICE" uptime:10 error:&error]&&error);
        NSString *want=[NSString stringWithFormat:TIOText(@"ota.identity.manifestRows"),TIO_FW_NAME,(unsigned long)expected,(unsigned long)(n-1)];
        assert([error.localizedDescription isEqual:want]);assert([g.status[@"stage"] intValue]==0);
        assert(![g allows:F(4,@{@"Mode":@2},nil) device:@"TEST_DEVICE" uptime:11]);
        assert([fm removeItemAtURL:root error:nil]);
        NSLog(@"PASS: a manifest of %lu rows against %lu member pins is refused before any transfer: %@",(unsigned long)rows.count,(unsigned long)n,want);
        return 0;
    }
    assert([mode isEqual:@"pins"]);
    // The exact folder passes with every pinned member checked.
    NSDictionary *good=TIOCheckExperimentalOTADirectory(folder,&error);assert(good&&!error);
    assert([good[@"checkedMembers"] unsignedIntegerValue]==n);
    NSDictionary *files=TIOCopyExperimentalOTAPayloads(folder,&error);assert(files.count==n);
    // The manifest has one row per payload: every member but itself, each a flat pinned name.
    NSArray *manifest=[NSJSONSerialization JSONObjectWithData:files[@"OtaFileInfo.json"] options:0 error:nil];
    assert([manifest isKindOfClass:NSArray.class]&&manifest.count==n-1);
    NSMutableSet *rowNames=[NSMutableSet setWithObject:@"OtaFileInfo.json"];NSMutableArray *nestedRows=[NSMutableArray new];
    for(NSDictionary *row in manifest){
        NSString *name=row[@"Name"];assert([name isKindOfClass:NSString.class]&&![name containsString:@"/"]&&pins[name]);[rowNames addObject:name];
        NSString *burn=row[@"BurnPath"];
        // A BurnPath in a subfolder is the glasses' install path only; the member itself is flat in the folder.
        if([burn isKindOfClass:NSString.class]&&[burn containsString:@"/"]){
            assert([burn.lastPathComponent isEqual:name]);[nestedRows addObject:row];
            BOOL dir=YES;assert([fm fileExistsAtPath:[folder URLByAppendingPathComponent:name].path isDirectory:&dir]&&!dir);
        }
    }
    assert([rowNames isEqualToSet:[NSSet setWithArray:pins.allKeys]]);
    // The exact archive: every member but the manifest and the AP is unchanged.
    NSDictionary *archive=TIOCheckExperimentalOTA([NSData dataWithContentsOfFile:@(argv[2])],&error);
    assert(archive&&[archive[@"unchangedPayloadCount"] unsignedIntegerValue]==n-2);
    // The unchanged flash gate takes this folder through a whole transfer: Mode 2, the target version, the
    // manifest of n-1 rows (a manifest one row short is refused) and every slice of every member, in order.
    {
        TIOOTAFlashGate *g=[TIOOTAFlashGate new];error=nil;assert([g prepareDirectory:folder device:@"TEST_DEVICE" uptime:10 error:&error]&&!error);
        TIOOTAFlashGate *shortGate=[TIOOTAFlashGate new];assert([shortGate prepareDirectory:folder device:@"TEST_DEVICE" uptime:10 error:nil]);
        assert([shortGate allows:F(4,@{@"Mode":@2},nil) device:@"TEST_DEVICE" uptime:11]&&[shortGate allows:F(5,@{@"OtaVersion":TIO_FW_OTA_VERSION},nil) device:@"TEST_DEVICE" uptime:12]);
        assert(![shortGate allows:F(6,[manifest subarrayWithRange:NSMakeRange(0,manifest.count-1)],nil) device:@"TEST_DEVICE" uptime:13]);
        assert([g allows:F(4,@{@"Mode":@2},nil) device:@"TEST_DEVICE" uptime:11]);
        assert([g allows:F(5,@{@"OtaVersion":TIO_FW_OTA_VERSION},nil) device:@"TEST_DEVICE" uptime:12]);
        assert([g allows:F(6,manifest,nil) device:@"TEST_DEVICE" uptime:13]);
        NSUInteger slices=0,total=0;
        for(NSDictionary *row in manifest){NSData *file=files[row[@"Name"]];
            for(NSUInteger at=0;at<file.length;at+=51200){NSUInteger size=MIN((NSUInteger)51200,file.length-at);
                assert([g allows:F(7,@{@"Name":row[@"Name"],@"Start":@(at),@"Size":@(size)},[file subdataWithRange:NSMakeRange(at,size)]) device:@"TEST_DEVICE" uptime:14]);slices++;total+=size;}}
        assert([g.status[@"validatedSlices"] unsignedIntegerValue]==slices&&[g.status[@"validatedSliceBytes"] unsignedIntegerValue]==total);
        NSUInteger want=0;for(NSString *name in pins)if(![name isEqual:@"OtaFileInfo.json"])want+=[pins[name][0] unsignedIntegerValue];assert(total==want);
        printf("gate transfer: %lu slices, %lu bytes over %lu manifest rows\n",(unsigned long)slices,(unsigned long)total,(unsigned long)manifest.count);
    }
    // Near misses of the folder: each one refused.
    NSArray *names=[pins.allKeys sortedArrayUsingSelector:@selector(compare:)];
    NSURL *missing=Copy(folder,root,@"missing");assert([fm removeItemAtURL:[missing URLByAppendingPathComponent:names.lastObject] error:nil]);
    assert(!TIOCheckExperimentalOTADirectory(missing,nil));
    NSURL *extra=Copy(folder,root,@"extra");assert([[NSData data] writeToURL:[extra URLByAppendingPathComponent:@"rives.bin.extra"] atomically:NO]);
    assert(!TIOCheckExperimentalOTADirectory(extra,nil));
    NSURL *dir=Copy(folder,root,@"subfolder-entry");assert([fm createDirectoryAtURL:[dir URLByAppendingPathComponent:@"loadable"] withIntermediateDirectories:NO attributes:nil error:nil]);
    assert(!TIOCheckExperimentalOTADirectory(dir,nil));
    // A member placed at its BurnPath subfolder instead of flat is refused (the flat name is missing and
    // the folder holds a directory).
    for(NSDictionary *row in nestedRows){
        NSURL *moved=Copy(folder,root,[@"burnpath-" stringByAppendingString:row[@"Name"]]);NSURL *target=[moved URLByAppendingPathComponent:row[@"BurnPath"]];
        assert([fm createDirectoryAtURL:target.URLByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil]);
        assert([fm moveItemAtURL:[moved URLByAppendingPathComponent:row[@"Name"]] toURL:target error:nil]);
        assert(!TIOCheckExperimentalOTADirectory(moved,nil));
        // The same file both flat and in the subfolder: still refused (an entry that is not a pin).
        assert([fm copyItemAtURL:target toURL:[moved URLByAppendingPathComponent:row[@"Name"]] error:nil]);
        assert(!TIOCheckExperimentalOTADirectory(moved,nil));
    }
    assert([fm removeItemAtURL:root error:nil]);
    NSLog(@"PASS: %@ (%@): %lu members and a %lu-row manifest from its pins, archive reports %lu unchanged payloads; %lu row(s) with a subfolder BurnPath kept flat in the folder; missing, extra, subfolder entry and BurnPath-placed members refused",
        TIO_FW_NAME,TIO_FW_BASE,(unsigned long)n,(unsigned long)manifest.count,(unsigned long)(n-2),(unsigned long)nestedRows.count);
}return 0;}
